parameters.jsCode:
// Inject default output if an individual agent fails or returns empty data
const research = $('Node 3: Research Agent').first()?.json?.text || "FALLBACK: Research findings unavailable due to agent timeout.";
const finance = $('Node 4: Finance Agent').first()?.json?.text || "FALLBACK: Finance baseline defaults applied.";
const marketing = $('Node 5: Marketing Agent').first()?.json?.text || "FALLBACK: Marketing channels defaulted to direct outbound.";

return [{
  json: {
    research_output: research,
    finance_output: finance,
    marketing_output: marketing
  }
}];

parameters.text:
=You are the Boardroom Challenger Agent. Review the department findings:

RESEARCH: {{ $json.research_output }}
FINANCE: {{ $json.finance_output }}
MARKETING: {{ $json.marketing_output }}

CRITICAL MANDATE: You must question or reject at least one material recommendation or assumption made by Finance or Marketing. Point out why their strategy is overly optimistic or risky, and demand a justification.

=You are the CEO Agent. Your job is to compare alternatives, resolve conflicts, and issue the final company decision.

INPUT TRACE:
Research Findings: {{ $('Node 7: Fallback Handler').item.json.research_output }}
Finance Findings: {{ $('Node 7: Fallback Handler').item.json.finance_output }}
Marketing Findings: {{ $('Node 7: Fallback Handler').item.json.marketing_output }}
Challenger Debate: {{ $('Node 8:Challenger Agent').item.json.text }}
Strategy Alternatives: {{ $('Node 9: Strategy Generator Agent').item.json.text }}

Respond strictly in valid JSON using this format:
{
  "final_decision": "One clear statement defining the selected strategy.",
  "department_evidence": "Summary of evidence used from Research, Finance, and Marketing.",
  "rejected_alternative": "State which strategy was rejected and why.",
  "tradeoffs_and_risks": "Important trade-offs and risks accepted.",
  "implementation_roadmap": [
    {"step": 1, "function": "Finance", "action": "..."},
    {"step": 2, "function": "Marketing", "action": "..."},
    {"step": 3, "function": "Operations", "action": "..."}
  ],
  "business_kpis": [
    "KPI 1 (Measurable target)",
    "KPI 2 (Measurable target)",
    "KPI 3 (Measurable target)"
  ]
}

